def quotes_projection(document):
 try:
  from scripts.baseline.r2_contracts_transport_contract import contracts_projection
 except ModuleNotFoundError:
  from r2_contracts_transport_contract import contracts_projection
 result=contracts_projection(document);paths=result['paths'];schemas=result['components']['schemas']
 if not(any(k in paths for k in PATH_DIGESTS) or any(k in schemas for k in SCHEMA_DIGESTS) or 'QUOTE_READ' in schemas['GrantableAuthorityCodeV1']['enum']):return result
 for section,pins in ((paths,PATH_DIGESTS),(schemas,SCHEMA_DIGESTS)):
  for key,pin in pins.items():
   if digest(section.pop(key,None))!=pin:raise ValueError('T07 exact contract required: '+key)
 for key,pin in CHANGED_DIGESTS.items():
  if digest(schemas[key])!=pin:raise ValueError('T07 exact addition required: '+key)
  schemas[key]=deepcopy(PREVIOUS_SCHEMAS[key])
 return result
